import java.util.*;

class Solution {
  public int maxScore(List<List<Integer>> grid) {
    int n = grid.size();
    List<Integer>[] rows = new List[101];
    for (int v = 1; v <= 100; v++) rows[v] = new ArrayList<>();
    for (int r = 0; r < n; r++) for (int v : grid.get(r)) if (!rows[v].contains(r)) rows[v].add(r);
    int[] dp = new int[1 << n];
    for (int v = 1; v <= 100; v++) {
      int[] next = dp.clone();
      for (int mask = 0; mask < (1 << n); mask++) {
        for (int r : rows[v])
          if ((mask & (1 << r)) == 0)
            next[mask | (1 << r)] = Math.max(next[mask | (1 << r)], dp[mask] + v);
      }
      dp = next;
    }
    int ans = 0;
    for (int x : dp) ans = Math.max(ans, x);
    return ans;
  }
}
